-- 📚 꼭집 주거 사전 — 행복주택 최대 거주기간 — 신혼부부·한부모 무자녀 10년·자녀 14년 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.8초 · 결과:
-- {"anns": 29, "by_std": {"행복주택": 24, "행복주택(신혼희망)": 5}, "무자녀10자녀14": 12, "무자녀10자녀14_ex": ["2015122300020859", "2015122300020858", "2015122300020854"], "출생자녀성년": 14, "출생자녀성년_ex": ["2015122300020871", "2015122300020870", "2015122300020859"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' group by 1)q),'무자녀10자녀14',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'무자녀\s*\(\s*10\s*년\s*\)\s*,?\s*자녀\s*1\s*명\s*이상\s*\(\s*14\s*년\s*\)'),'무자녀10자녀14_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'무자녀\s*\(\s*10\s*년\s*\)\s*,?\s*자녀\s*1\s*명\s*이상\s*\(\s*14\s*년\s*\)' order by 1 desc limit 3)q),'출생자녀성년',(select count(distinct announcement_id) from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'2024\s*년\s*1\s*월\s*1\s*일\s*이후\s*출생'),'출생자녀성년_ex',(select json_agg(i) from(select distinct announcement_id i from y where std in('행복주택','행복주택(신혼희망)') and cls='최대 거주기간·임대기간' and t~'2024\s*년\s*1\s*월\s*1\s*일\s*이후\s*출생' order by 1 desc limit 3)q))j;
